def build(i, s):
    title, people, framing, man, scene, refs, worn = s
    urls, lines, n = [], [], 0
    for rk, sk in refs:
        nums = []
        for fn in R[rk]:
            urls.append(P + fn); n += 1; nums.append(f"#{n}")
        lines.append(f"- {SPEC[sk]} (reference image{'s' if len(nums) > 1 else ''} {', '.join(nums)})")
    shoes = any(rk.startswith("loafer") or rk in ("notte_set", "tabacco_set", "supremo_set") for rk, _ in refs)
    parts = [scene]
    if people:
        if man and framing != "detail":
            parts.append(f"The man: {MEN[man]}. {REAL}")
        elif framing == "detail":
            parts.append("Real skin on the hands with visible veins, knuckle creases and natural nails. Real fabric behaviour and real optics: film grain, slight lens softness, no retouching.")
        parts.append("He wears only these ModernoMilano pieces and nothing else:\n" + "\n".join(lines))
    else:
        parts.append("The only clothing in the picture is these ModernoMilano pieces:\n" + "\n".join(lines))
    parts.append(f"How they are worn or arranged: {worn}")
    parts.append("Reproduce every piece exactly as in its reference images: same colour and shade, same knit or fabric, same collar, same buttons or zip, same pockets, same stripes or trim, same length and fit. Do not redesign, simplify or add anything.")
    if people:
        rules = ["His hands and wrists are bare: no ring, no watch, no bracelet."]
        if shoes:
            rules.append("Loafers are worn without socks, ankles bare.")
        elif framing in ("full-body",):
            raise SystemExit(f"{i}: full-body without loafers")
        elif framing != "detail":
            rules.append("His feet are not in the picture.")
        rules.append("He is the only person in the picture.")
        parts.append(" ".join(rules))
    else:
        parts.append("There are no people in the picture.")
    parts.append("No logos, labels, badges or readable text anywhere in the picture. Photographic, not CGI.")
    return {"n": i, "title": title, "people": people, "framing": framing, "refs": urls, "prompt": "\n\n".join(parts)}

if __name__ == "__main__":
    out = [build(i, s) for i, s in enumerate(S, 1)]
    assert len(out) == 50, len(out)
    json.dump(out, open(sys.argv[1], "w"), indent=1)
    print(len(out), "shots,", len({u for o in out for u in o["refs"]}), "unique refs, max refs", max(len(o["refs"]) for o in out))
